purpose: Report the dimension types that no dimension uses.
code:
var used = new HashSet<long>(new FilteredElementCollector(doc).OfClass(typeof(Dimension)).Select(d => d.GetTypeId().Value));
var report = new List<string>();
using (var t = new Transaction(doc, "Unused dimension types"))
{
    t.Start();
    foreach (DimensionType dt in new FilteredElementCollector(doc).OfClass(typeof(DimensionType)).Cast<DimensionType>().ToList())
    {
        if (used.Contains(dt.Id.Value) || dt.Name.StartsWith("Default")) continue;
        report.Add(dt.Name);
        doc.Delete(dt.Id);
    }
    t.Commit();
}
return string.Join("\n", report);

