purpose: Dry run: resize the supply ducts on Level 2 to 400 x 250 and count the open ends.
code:
bool COMMIT = false;
var log = new List<string>();
var tg = new TransactionGroup(doc, "Resize SA ducts"); tg.Start();
try
{
    using (var t = new Transaction(doc, "Resize"))
    {
        t.Start();
        foreach (Duct d in new FilteredElementCollector(doc).OfClass(typeof(Duct)).Cast<Duct>().Where(x => x.ReferenceLevel.Name == "Level 2"))
        {
            d.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM).Set(400 / 304.8);
            d.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM).Set(250 / 304.8);
            log.Add("RESIZED " + d.Id);
        }
        t.Commit();
    }
    log.Add("open ends: " + new FilteredElementCollector(doc).OfClass(typeof(Duct)).Cast<Duct>().Sum(x => x.ConnectorManager.UnusedConnectors.Size));
}
finally { if (COMMIT) tg.Assimilate(); else tg.RollBack(); }
return string.Join("\n", log);

purpose: Check which walls in the active view can be deleted without errors; keep the model as it is.
code:
var ok = new List<long>(); var bad = new List<long>();
var walls = new FilteredElementCollector(doc, doc.ActiveView.Id).OfClass(typeof(Wall)).ToElementIds();
using (var t = new Transaction(doc, "Probe wall delete"))
{
    t.Start();
    foreach (var id in walls)
    {
        try { doc.Delete(id); ok.Add(id.Value); }
        catch (Autodesk.Revit.Exceptions.ArgumentException) { bad.Add(id.Value); }
    }
    t.RollBack();
}
return "deletable " + ok.Count + ", blocked " + bad.Count;

purpose: Count the doors on each level.
code:
var counts = new Dictionary<string, int>();
using (var t = new Transaction(doc, "Door count"))
{
    t.Start();
    foreach (FamilyInstance d in new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Doors).OfClass(typeof(FamilyInstance)))
    {
        var lvl = doc.GetElement(d.LevelId)?.Name ?? "none";
        counts[lvl] = counts.TryGetValue(lvl, out var n) ? n + 1 : 1;
        d.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("counted");
    }
    t.Commit();
}
return string.Join("\n", counts.Select(kv => kv.Key + ": " + kv.Value));

