using (var t = new Transaction(doc, "Door marks"))
{
    t.Start();
    var phase = doc.Phases.Cast<Phase>().Last();
    foreach (FamilyInstance d in new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Doors).OfClass(typeof(FamilyInstance)))
    {
        var room = d.get_ToRoom(phase) ?? d.get_FromRoom(phase);
        if (room != null) d.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set(room.Number);
    }
    t.Commit();
}
return "done";

